    code("freeze=json.loads((ROOT/'inputs/freeze.json').read_text(encoding='utf-8'))\nsource=ROOT.parent/'customer-support'\nfor name,h in freeze['source_hashes'].items():\n    assert hashlib.sha256((source/name).read_bytes()).hexdigest()==h,name\nprint('Historical workbook, predictions, prompts and annotation evidence unchanged.')\nfor r in rows:\n    raw=json.loads((ROOT/'runs'/(r['id']+'.json')).read_text(encoding='utf-8'))\n    assert raw['prediction']==r['v3_prediction']\n    assert raw['request']['messages'][1]['content']==r['query']\n    assert raw['request']['model']=='gpt-4o-mini' and raw['request']['temperature']==0\nprint('All100 saved predictions match actual response records; labels are not sent as query data.')\nprint(json.loads((ROOT/'results/langsmith_sync_status.json').read_text()))")
